-- PROPOSTA COMPLEMENTAR: NÃO EXECUTADA, REQUER GOVERNANÇA E HOMOLOGAÇÃO.
-- Aplicar SOMENTE após adoção controlada da proposta principal (incluindo serviço 'ao').
BEGIN;
insert into public.service_catalog_versions(service_code,version,snapshot,contract_master_version,created_by)
select code,version,to_jsonb(s),last_contract_master_version,null from public.service_catalog s where code in ('c','k','l','m','ao') on conflict(service_code,version) do nothing;
insert into public.service_level_scope_versions(service_code,level_code,version,snapshot,created_by)
select service_code,level_code,version,to_jsonb(s),null from public.service_level_scope_catalog s where service_code in ('c','k','l','m','ao') on conflict(service_code,level_code,version) do nothing;
update public.service_catalog set exclusions=case when not (exclusions @> '["Documentação complementar necessária à Prefeitura, além dos projetos expressamente contratados e ARTs obrigatórias, não será elaborada, obtida ou custeada pela contratada. Documentos de terceiros (certidões, matrículas, procurações, laudos e topografia) e taxas da prefeitura são responsabilidade exclusiva do contratante. A taxa da ART também é integralmente custeada pelo contratante, mediante adiantamento ou reembolso comprovado quando o recolhimento operacional couber à profissional. Mantêm-se as correções de erros técnicos próprios e os documentos integrantes do projeto contratado."]'::jsonb) then exclusions || '["Documentação complementar necessária à Prefeitura, além dos projetos expressamente contratados e ARTs obrigatórias, não será elaborada, obtida ou custeada pela contratada. Documentos de terceiros (certidões, matrículas, procurações, laudos e topografia) e taxas da prefeitura são responsabilidade exclusiva do contratante. A taxa da ART também é integralmente custeada pelo contratante, mediante adiantamento ou reembolso comprovado quando o recolhimento operacional couber à profissional. Mantêm-se as correções de erros técnicos próprios e os documentos integrantes do projeto contratado."]'::jsonb else exclusions end,
  version=version+1,updated_at=now() where code in ('c','k','l','m','ao') and not (exclusions @> '["Documentação complementar necessária à Prefeitura, além dos projetos expressamente contratados e ARTs obrigatórias, não será elaborada, obtida ou custeada pela contratada. Documentos de terceiros (certidões, matrículas, procurações, laudos e topografia) e taxas da prefeitura são responsabilidade exclusiva do contratante. A taxa da ART também é integralmente custeada pelo contratante, mediante adiantamento ou reembolso comprovado quando o recolhimento operacional couber à profissional. Mantêm-se as correções de erros técnicos próprios e os documentos integrantes do projeto contratado."]'::jsonb);
update public.service_level_scope_catalog s set
 budget_description=v.budget_description,contract_scope=v.contract_scope,annex_scope=v.annex_scope,review_status='pending',
 version=s.version+1,updated_at=now(),source_service_version=(select version from public.service_catalog where code=s.service_code)
from (values
('ao','bronze','Emissão e Regularização de ART — nível BRONZE. Registro, complementação, substituição, regularização ou baixa de ART apenas para atividades técnicas efetivamente assumidas por profissional habilitado; registro legalmente obrigatório para projeto não é facultativo. Nível: execução essencial com produtos técnicos mínimos selecionados no orçamento. Entregas, abrangência, preços, prazos, visitas e revisões exigem definição individual no orçamento e Anexo I. ART de execução não está incluída em projeto; ART legalmente exigível para serviço técnico é obrigatória com custeio previamente definido. As taxas de ART são 100% custeadas pelo CONTRATANTE, fora dos honorários, por adiantamento ou reembolso comprovado quando o recolhimento for realizado pela CONTRATADA, respeitadas as regras operacionais do CREA. A CONTRATADA providenciará as ARTs legalmente exigíveis dos serviços técnicos por ela assumidos. ART de execução de obra não está incluída sem contratação e assunção real da execução.','A CONTRATADA prestará Emissão e Regularização de ART, nível BRONZE, exclusivamente nos limites, quantidades e etapas do Anexo I. Objeto: Registro, complementação, substituição, regularização ou baixa de ART apenas para atividades técnicas efetivamente assumidas por profissional habilitado; registro legalmente obrigatório para projeto não é facultativo. Entregáveis possíveis mediante contratação: conferência de objeto e documentos; cadastramento de ART cabível; comprovante após registro e taxa; orientação sobre complementação/baixa quando contratada. Exclusões do serviço: ART de execução sem contratação da atividade executiva; assunção fictícia de responsabilidade de terceiros; taxa do CREA quando não discriminada. execução essencial com produtos técnicos mínimos selecionados no orçamento. A contratação não afasta registro de ART legalmente exigível nem transfere responsabilidade de execução de obra. As taxas de ART são 100% custeadas pelo CONTRATANTE, fora dos honorários, por adiantamento ou reembolso comprovado quando o recolhimento for realizado pela CONTRATADA, respeitadas as regras operacionais do CREA. A CONTRATADA providenciará as ARTs legalmente exigíveis dos serviços técnicos por ela assumidos. ART de execução de obra não está incluída sem contratação e assunção real da execução.','ATIVIDADE: Emissão e Regularização de ART • NÍVEL BRONZE. OBJETO: Registro, complementação, substituição, regularização ou baixa de ART apenas para atividades técnicas efetivamente assumidas por profissional habilitado; registro legalmente obrigatório para projeto não é facultativo. ENTREGÁVEIS A ASSINALAR E QUANTIFICAR: conferência de objeto e documentos; cadastramento de ART cabível; comprovante após registro e taxa; orientação sobre complementação/baixa quando contratada. PARÂMETROS OBRIGATÓRIOS: atividade e atribuições; contratante, local e contrato; tipo de ART; valor/condição de taxa; prazo/protocolo. EXCLUSÕES ESPECÍFICAS: ART de execução sem contratação da atividade executiva; assunção fictícia de responsabilidade de terceiros; taxa do CREA quando não discriminada. NÍVEL: execução essencial com produtos técnicos mínimos selecionados no orçamento. [QUANTIDADES, PRANCHAS, FORMATOS, VISITAS, REVISÕES, PRAZOS, VALORES E CUSTEIO DE ART A DEFINIR]. Nenhum campo pendente pode ser presumido incluído ou publicado como texto definitivo. As taxas de ART são 100% custeadas pelo CONTRATANTE, fora dos honorários, por adiantamento ou reembolso comprovado quando o recolhimento for realizado pela CONTRATADA, respeitadas as regras operacionais do CREA. A CONTRATADA providenciará as ARTs legalmente exigíveis dos serviços técnicos por ela assumidos. ART de execução de obra não está incluída sem contratação e assunção real da execução.'),
